sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_zoom;
uniform float amzp_flakeSize;
uniform float amzp_fallX;
uniform float amzp_fallY;
uniform float amzp_spinAmt;
uniform float amzp_wobble;
layout(color) uniform half4 amzp_flakeCol;
uniform float amzp_showBg;
layout(color) uniform half4 amzp_skyA;
layout(color) uniform half4 amzp_skyB;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxsc) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxsc;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 stdFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q.y = -q.y;
        q = nmStd(q, pxs());
        q.y = -q.y;
        return q + 0.5 * W;
    }
    const float NMCUT = 0.04;
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) {
            float na = clamp((f.a - NMCUT) / (1.0 - NMCUT), 0.0, 1.0);
            o = float4(f.rgb * (na / max(f.a, 0.0001)), na);
        }
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float2 hsh(float2 p) { p += amzp_seed * 1.37; p = float2(dot(p, float2(127.1, 311.7)), dot(p, float2(269.5, 183.3))); return fract(sin(p) * 43758.5453); }
    float s01(float x) { return sin(x) * 0.5 + 0.5; }
    float3 voro(float2 x, float T, out float2 cid) {
        float2 n = floor(x), f = fract(x);
        float2 mg = float2(0.0), mr = float2(0.0);
        float md = 8.0;
        for (int j = -1; j <= 1; j++)
        for (int i = -1; i <= 1; i++) {
            float2 g = float2(float(i), float(j));
            float2 o = 0.5 + amzp_wobble * sin(T * 0.5 + 6.2831 * hsh(n + g));
            float2 r = g + o - f;
            float d = dot(r, r);
            if (d < md) { md = d; mr = r; mg = g; }
        }
        md = 8.0;
        for (int j = -2; j <= 2; j++)
        for (int i = -2; i <= 2; i++) {
            float2 g = mg + float2(float(i), float(j));
            float2 o = 0.5 + amzp_wobble * sin(T * 0.5 + 6.2831 * hsh(n + g));
            float2 r = g + o - f;
            if (dot(mr - r, mr - r) > 0.000001) md = min(md, dot(0.5 * (mr + r), normalize(r - mr)));
        }
        cid = n + mg;
        return float3(md, mr);
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 I = stdFC();
        float T = TT();
        float2 p = (I - W * 0.5) / W.x;
        p += T * float2(amzp_fallX, amzp_fallY);
        float2 cid;
        float3 c = voro(p / max(amzp_zoom, 0.001), T, cid);
        float cd = length(c.yz);
        float amzLocal_size = mix(0.1, 0.2, s01(cid.x - cid.y)) * amzp_flakeSize;
        float fang = atan(c.z, c.y);
        float angvel = sin(cid.x * 123.0 + cid.y * 451.0) * 0.5 * 3.14159265 * amzp_spinAmt;
        fang += T * angvel;
        float np = floor(mix(5.0, 9.0, s01(cid.x + cid.y)));
        float pv = s01(fang * np);
        float w1 = pow(pv, 4.0);
        float nr = floor(mix(1.0, 4.0, s01(cid.x * 100.0 + cid.y * 42.0)));
        float pv2 = pv;
        if (hsh(cid).x < 0.5) pv2 = 1.0 - pv;
        float wd = mix(cd * 0.8, cd, pv2);
        float rv = s01(wd / max(amzLocal_size * 0.8, 1e-4) * 2.0 * 3.14159265 * nr - 3.14159265 * 0.5);
        float w2 = pow(rv, 2.0);
        float wht = 1.0 - (1.0 - w1) * (1.0 - w2);
        float al = wht * (1.0 - smoothstep(amzLocal_size * 0.8, amzLocal_size, cd));
        float4 G = float4(amzp_flakeCol.rgb * al, al);
        if ((amzp_showBg>0.5)) {
            float3 sky = mix(amzp_skyA.rgb, amzp_skyB.rgb, clamp(amzLayerNorm().y, 0.0, 1.0));
            G = float4(mix(sky, amzp_flakeCol.rgb, al), 1.0);
        }
        amzOutput = nmBlend(orig, nmGradMap(G));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
